3	import com.example.starter.rolling.api.dto.ValidationErrorResponse;
4	import com.example.starter.rolling.service.BusinessException;
5	import com.example.starter.rolling.service.ConflictException;
6	import com.example.starter.rolling.service.ValidationException;
7	import org.springframework.http.ResponseEntity;
8	import org.springframework.web.bind.annotation.ExceptionHandler;
9	import org.springframework.web.bind.annotation.RestControllerAdvice;
10	
11	import java.util.Map;
12	
13	/**
14	 * 业务异常到 HTTP 状态码的统一映射。
15	 */
16	@RestControllerAdvice
17	public class GlobalExceptionHandler {
18	
19	    @ExceptionHandler(ValidationException.class)
20	    public ResponseEntity<ValidationErrorResponse> handleValidation(ValidationException ex) {
21	        return ResponseEntity.unprocessableEntity()
22	                .body(new ValidationErrorResponse("SCHEDULE_VIOLATION", ex.getMessage(), ex.getViolations()));
23	    }
24	
25	    @ExceptionHandler(ConflictException.class)
26	    public ResponseEntity<Map<String, String>> handleConflict(ConflictException ex) {
27	        return ResponseEntity.status(ex.getStatus()).body(Map.of("code", "CONFLICT", "message", ex.getMessage()));
28	    }
29	
